exec(open(__file__.replace('repair-final-sources.py','repair.py')).read().split("step('lem-cm-lattice")[0])
step('lem-cm-strong-solution-smoothness-bootstrap','3.1',r'**Induction step.** Suppose $u$ is $C^r$ into every $H^p$, with $r\ge1$. For any target order $p$, choose $q>\max(p,3/2)$. The product bound [F2] makes $(f,g)\mapsto(f\cdot\nabla)g$ a continuous bilinear map $H^{q+1}\times H^{q+1}\to H^q\subseteq H^p$. Applying the ordinary bilinear product rule [F3] repeatedly therefore shows that $t\mapsto(u\cdot\nabla)u$ is $C^r$ into $H^p$; its derivatives through order $r$ use only derivatives of $u$ already supplied by the induction hypothesis. Likewise $\Delta:H^{p+2}\to H^p$ and $P:H^p\to H^p$ are bounded linear maps [F4,F5], so $G=\nu\Delta u-P((u\cdot\nabla)u)$ is $C^r$ into $H^p$. Since $u\prime=G$, this proves $u$ is $C^{r+1}$ into $H^p$, with derivative of order $r+1$ equal to the formal Leibniz expression. No differentiability of $u^{(r+1)}$ was assumed to reach this conclusion. As $p$ was arbitrary, induction proves the claim of step 2.2. [step 2.2, F2, F3, F4, F5]')
step('lem-periodic-pressure-reconstruction','1.1',r'**The multiplier identity.** Put $v=(u\cdot\nabla)u$ and $S_k:=\sum_{i,j}k_ik_j\widehat{u_iu_j}(k)$. By [F1], $k\cdot\widehat v(k)=2\pi iS_k$ for $k\ne0$. The projection formula [F2] gives $\widehat{(I-P)v}(k)=2\pi i kS_k/|k|_2^2$, while the stated pressure definition gives $\widehat{\nabla p}(k)=2\pi i k\widehat p(k)=-2\pi i kS_k/|k|_2^2$. At $k=0$ both coefficients are zero, because gradients have zero constant coefficient and $P$ is the identity on that mode. Thus $\nabla p=-(I-P)v$ coefficientwise; the smoothness and coefficient identification justified in step 3.1 below turn it into the claimed field identity. [F1, F2]')
replace('lem-periodic-pressure-reconstruction',r'$+\sum_{i,j}(2\pi ik_i)(2\pi ik_j)\widehat{u_iu_j}(k)=4\pi^2',r'$-\sum_{i,j}(2\pi ik_i)(2\pi ik_j)\widehat{u_iu_j}(k)=4\pi^2')
p=ROOT/'items/lem-periodic-pressure-reconstruction.md';s=p.read_text()
a=s.index('3.1 **Decay');b=s.index('\n\n',a)
s=s[:a]+r'3.1 **Bounded multiplier and smoothness.** Since $|k_ik_j|/|k|_2^2\le1$ for $k\ne0$, the pressure coefficient map satisfies $\|p\|_{H^r}\le\sum_{i,j}\|u_iu_j\|_{H^r}$ by the triangle inequality, for every real $r$. For $r>3/2$ each product is continuous into $H^r$ by [F3]; larger orders give the assertion also for any smaller order by the monotonicity of the Sobolev weights. The hypotheses of the smoothness bootstrap [[lem-cm-strong-solution-smoothness-bootstrap]] hold for $u$, so all its time derivatives are continuous into every $H^r$. The bilinear product rule makes the same true for $u_iu_j$, and the bounded coefficient multiplier defining $p$ commutes with those derivatives. Applying [F4] at arbitrarily high orders proves joint spatial and time smoothness and identifies the coefficients of all derivatives. Finally $\widehat p(0)=0$ gives the zero mean. This proves claim 1. [F3, F4, given]'+s[b:]
p.write_text(s)
